def coinChange(coins: List[int], amount: int) -> int:
    if amount == 0:
        return 0
    from collections import deque
    queue = deque([(0, 0)])
    visited = {0}
    while queue:
        curr, steps = queue.popleft()
        if curr == amount:
            return steps
        for coin in coins:
            nxt = curr + coin
            if nxt <= amount and nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, steps + 1))
    return -1

