def coinChange(coins: List[int], amount: int) -> int:
    def dfs(index: int, rem: int) -> float:
        if rem == 0:
            return 0
        if index >= len(coins) or rem < 0:
            return float('inf')

        min_coins = float('inf')
        qty = 0
        while qty * coins[index] <= rem:
            res = dfs(index + 1, rem - qty * coins[index])
            if res != float('inf'):
                min_coins = min(min_coins, qty + res)
            qty += 1
        return min_coins

    ans = dfs(0, amount)
    return int(ans) if ans != float('inf') else -1

